  (
   input  logic clk0_i,
   input  logic clk1_i,
   input  logic clk_sel_i,
   output logic clk_o
   );
always_comb
     begin
        if (clk_sel_i == 1'b0)
           clk_o = clk0_i;
        else
           clk_o = clk1_i;
     end
endmodule

module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
reg [7:0] counter;
    reg tick;
    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            tick <= 0;
        end else begin
            if (counter == div - 1) begin
                counter <= 0;
                tick <= 1;
            end else begin
                counter <= counter + 1;
                tick <= 0;
            end
        end
    end
endmodule

