module top_properties (input logic clock, read, write, ready);
`ifdef FAIL
    logic [31:0] fail;
`endif
    property read_write(clock, read, write, ready);
        @(posedge clock) if (read) begin
            if (write) begin
                $display("read and write are asserted simultaneously");
                $display("read: %b, write: %b", read, write);
                $display("ready: %b", ready);
                $display("fail: %b", fail);
                $finish;
            end
        end
    endproperty
    assert property (read_write(clock, read, write, ready));
    property ready_write(clock, read, write, ready);
        @(posedge clock) if (write) begin
            if (ready) begin
                if (FAIL) begin
                    @(posedge clock) if (!write) begin
                        $display("ready and write are asserted simultaneously");
                        $display("read: %b, write: %b", read, write);
                        $display("ready: %b", ready);
                        $display("fail: %b", fail);
                        $finish;
                    end
                end
            end
        end
    endproperty
    assert property (ready_write(clock, read, write, ready));
endmodule

