module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
reg [1:0]TxState;
reg [1:0]RxState;
reg [15:0]TxBdCount;
reg [15:0]RxBdCount;
reg [7:0]RxData;
reg [7:0]TxData;
assign opTxBusy = (TxState == Sending) ? 1'b1 : 1'b0;
assign opTx = (TxState == Sending) ? 1'b1 : 1'b0;
assign opRxData = (RxState == RxDone) ? RxData : 8'b0;
assign opRxValid = (RxState == RxDone) ? 1'b1 : 1'b0;
always @(posedge ipClk) begin
	if(ipReset) begin
		TxState <= TxIdle;
		RxState <= RxIdle;
		TxBdCount <= 16'b0;
		RxBdCount <= 16'b0;
		RxData <= 8'b0;
		TxData <= 8'b0;
		opTxBusy <= 1'b0;
		opTx <= 1'b0;
		opRxData <= 8'b0;
		opRxValid <= 1'b0;
	end else begin
		case(TxState)
			TxIdle: begin
				if(ipTxSend) begin
					TxState <= Sending;
					TxData <= 8'b00000001;
					TxBdCount <= 16'b0;
					opTxBusy <= 1'b1;
				end
			end
			Sending: begin
				if(TxBdCount == 16'b433) begin
					TxData <= {TxData[6:0],1'b1};
					TxState <= TxDone;
					TxBdCount <= 16'b0;
					opTxBusy <= 1'b0;
				end else begin
					TxData <= {TxData[6:0],1'b0};
					TxBdCount <= TxBdCount + 1'b1;
				end
			end
			TxDone: begin
				TxState <= TxIdle;
			end
			default: begin
				TxState <= TxIdle;
			end
		endcase
		case(RxState)
			RxIdle: begin
				if(ipRx == 1'b0) begin
					RxState <= Receiving;
					RxBdCount <= 16'b0;
					RxData <= 8'b0;
				end
			end
			Receiving: begin
				if(RxBdCount == 16'b433) begin
					RxData <= {RxData[6:0],ipRx};
					RxState <= RxDone;
					RxBdCount <= 16'b0;
				end else begin
					RxData <= {RxData[6:0],ipRx};
					RxBdCount <= RxBdCount + 1'b1;
				end
			end
			RxDone: begin
				RxState <= RxIdle;
			end
			default: begin
				RxState <= RxIdle;
			end
		endcase
	end
end
endmodule

