module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0]    mem [0:DEPTH-1];
reg [31:0]         word_count;
reg                full_p, empty_p, prog_full_p;
reg                overflow_p, underflow_p;

assign data_o = mem[word_count];
assign prog_full = prog_full_p;
assign full = full_p;
assign empty = empty_p;
assign overflow = overflow_p;
assign underflow = underflow_p;

always @(posedge clk) begin
    if (reset_p) begin
        word_count <= 0;
        full_p <= 0;
        empty_p <= 1;
        overflow_p <= 0;
        underflow_p <= 0;
    end else begin
        if (data_we) begin
            if (word_count < DEPTH-1) begin
                mem[word_count] <= data_i;
                word_count <= word_count + 1;
                full_p <= 0;
                empty_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end else begin
                mem[0] <= data_i;
                word_count <= 0;
                full_p <= 1;
                empty_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end
        end else begin
            if (word_count > 0) begin
                mem[word_count-1] <= mem[word_count];
                word_count <= word_count - 1;
                full_p <= 0;
                empty_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end else begin
                mem[DEPTH-1] <= mem[0];
                word_count <= DEPTH-1;
                full_p <= 0;
                empty_p <= 1;
                overflow_p <= 0;
                underflow_p <= 0;
            end
        end
        if (data_rd) begin
            if (word_count > 0) begin
                word_count <= word_count - 1;
                full_p <= 0;
                empty_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end else begin
                word_count <= DEPTH-1;
                full_p <= 0;
                empty_p <= 1;
                overflow_p <= 0;
                underflow_p <= 0;
            end
        end else begin
            if (word_count < DEPTH-1) begin
                word_count <= word_count + 1;
                full_p <= 0;
                empty_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end else begin
                word_count <= 0;
                full_p <= 0;
                empty_p <= 1;
                overflow_p <= 0;
                underflow_p <= 0;
            end
        end
        if (word_count == PROG_FULL) begin
            prog_full_p <= 1;
            full_p <= 1;
        end else begin
            prog_full_p <= 0;
            full_p <= 0;
        end
        if (word_count == 0) begin
            empty_p <= 1;
        end else begin
            empty_p <= 0;
        end
        if (word_count == DEPTH-1) begin
            overflow_p <= 1;
        end else begin
            overflow_p <= 0;
        end
        if (word_count == 0) begin
            underflow_p <= 1;
        end else begin
            underflow_p <= 0;
        end
    end
end

endmodule

