module counter
#(
  parameter integer WIDTH=5
 )
 (
  input  wire clk  ,
  input  wire rst  ,
  input  wire load ,
  input  wire enab ,
  input  wire [WIDTH-1:0] cnt_in ,
  output reg  [WIDTH-1:0] cnt_out 
 );
reg [WIDTH-1:0] cnt_tmp;
  always @(posedge clk, posedge rst, posedge load, posedge enab)
  begin
    if (rst)
    begin
      cnt_out <= {WIDTH{1'b0}};
    end
    else if (load)
    begin
      cnt_out <= cnt_in;
    end
    else if (enab)
    begin
      cnt_out <= cnt_tmp;
    end
    else
    begin
      cnt_out <= {WIDTH{1'b0}};
    end
  end
  always @(posedge clk)
  begin
    if (rst)
    begin
      cnt_tmp <= {WIDTH{1'b0}};
    end
    else if (load)
    begin
      cnt_tmp <= cnt_in;
    end
    else if (enab)
    begin
      cnt_tmp <= cnt_tmp + 1;
    end
    else
    begin
      cnt_tmp <= {WIDTH{1'b0}};
    end
  end
endmodule

