module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [1:0] NUM_STATES=4;
reg [1:0] current_state;
reg [1:0] next_state;
  always @(posedge clk, negedge resetn) begin
    if(!resetn) begin
      current_state <= 2'b00;
    end else begin
      current_state <= next_state;
    end
  end
  always @(*) begin
    case(current_state)
    2'b00 : begin
      if(go) begin
        next_state <= 2'b01;
      end
      else begin
        next_state <= 2'b00;
      end
    end
    2'b01 : begin
      if(WREADY) begin
        next_state <= 2'b10;
      end
      else begin
        next_state <= 2'b01;
      end
    end
    2'b10 : begin
      if(WREADY) begin
        next_state <= 2'b11;
      end
      else begin
        next_state <= 2'b10;
      end
    end
    2'b11 : begin
      next_state <= 2'b00;
    end
    default : begin
      next_state <= 2'b00;
    end
    endcase
  end
  always @(*) begin
    case(current_state)
    2'b00 : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h00;
      WVALID <= 1'b0;
    end
    2'b01 : begin
      done <= 1'b0;
      WDATA <= data;
      WSTRB <= 4'h0f;
      WVALID <= 1'b1;
    end
    2'b10 : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h00;
      WVALID <= 1'b0;
    end
    2'b11 : begin
      done <= 1'b1;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h00;
      WVALID <= 1'b0;
    end
    default : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h00;
      WVALID <= 1'b0;
    end
    endcase
  end
endmodule

