module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  assign io_ready = (state == 4'b0000) && (tick == 1'b1);
  assign tx = (state == 4'b0000) ? data[0] : 1'b0;
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'b0000;
      data <= 8'b00000000;
    end else if (tick) begin
      case (state)
        4'b0000: begin
          if (io_valid) begin
            data <= io_bits;
            state <= 4'b0001;
          end
        end
        4'b0001: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b0010;
          end
        end
        4'b0010: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b0011;
          end
        end
        4'b0011: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b0100;
          end
        end
        4'b0100: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b0101;
          end
        end
        4'b0101: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b0110;
          end
        end
        4'b0110: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b0111;
          end
        end
        4'b0111: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1000;
          end
        end
        4'b1000: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1001;
          end
        end
        4'b1001: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1010;
          end
        end
        4'b1010: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1011;
          end
        end
        4'b1011: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1100;
          end
        end
        4'b1100: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1101;
          end
        end
        4'b1101: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1110;
          end
        end
        4'b1110: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b1111;
          end
        end
        4'b1111: begin
          if (io_valid) begin
            data <= data >> 1;
            state <= 4'b0000;
          end
        end
        default: begin
          state <= 4'b0000;
        end
      endcase
    end
  end
endmodule

