module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );
reg [OUTPUT_BITS-1:0] mask_gen;
reg [OUTPUT_BITS-1:0] start_gen;
reg [OUTPUT_BITS-1:0] radicand_gen;
reg [OUTPUT_BITS-1:0] root_gen;

generate
  genvar i;
  for (i=0; i<OUTPUT_BITS; i=i+1) begin
    always @(posedge clk) begin
      if (reset_n == 1'b0) begin
        start_gen[i] <= 1'b0;
        radicand_gen[i] <= 1'b0;
        root_gen[i] <= 1'b0;
      end else begin
        if (start == 1'b1) begin
          start_gen[i] <= 1'b1;
          radicand_gen[i] <= radicand[i];
          root_gen[i] <= 1'b0;
        end else begin
          start_gen[i] <= 1'b0;
          radicand_gen[i] <= radicand_gen[i] - mask_gen[i] * root_gen[i];
          root_gen[i] <= root_gen[i] + mask_gen[i] * radicand_gen[i];
        end
      end
    end
  end
endgenerate

always @(posedge clk) begin
  if (reset_n == 1'b0) begin
    data_valid <= 1'b0;
  end else begin
    if (start == 1'b1) begin
      data_valid <= 1'b1;
    end else begin
      data_valid <= 1'b0;
    end
  end
end

assign mask_gen = {OUTPUT_BITS{1'b1}};
assign root = root_gen[OUTPUT_BITS-1:0];

endmodule

