module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam
    ZERO = 0,
    ONE  = 1,
    TWO  = 2;

    reg [1:0] state;
    reg [N-1:0] data_p1, data_p2;
    reg load_p1, load_p2, load_p1_from_p2;

    assign s_ready = (state == ZERO) || (state == ONE && load_p1_from_p2);
    assign m_data  = (state == TWO) ? data_p2 : data_p1;
    assign m_valid = (state == TWO) && load_p1_from_p2;

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            data_p1 <= 0;
            data_p2 <= 0;
            load_p1 <= 0;
            load_p2 <= 0;
            load_p1_from_p2 <= 0;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && m_ready) begin
                        state <= ONE;
                        data_p1 <= s_data;
                        load_p1 <= 1;
                    end
                end
                ONE: begin
                    if (s_valid && m_ready) begin
                        state <= TWO;
                        data_p2 <= s_data;
                        load_p2 <= 1;
                    end else if (s_valid && !m_ready) begin
                        state <= ZERO;
                        load_p1 <= 0;
                    end
                end
                TWO: begin
                    if (s_valid && m_ready) begin
                        state <= ONE;
                        data_p1 <= s_data;
                        load_p1 <= 1;
                    } else if (s_valid && !m_ready) begin
                        state <= ZERO;
                        load_p1 <= 0;
                    end else if (!s_valid && m_ready) begin
                        state <= TWO;
                        load_p1_from_p2 <= 1;
                    end
                end
                default: begin
                    state <= ZERO;
                    data_p1 <= 0;
                    data_p2 <= 0;
                    load_p1 <= 0;
                    load_p2 <= 0;
                    load_p1_from_p2 <= 0;
                end
            endcase
        end
    end
endmodule

