module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );
reg [31:0] Divisor_int;
	reg [31:0] Divider_int;
	reg [31:0] remainder_int;
	reg [31:0] result_int;
	reg [31:0] counter_int;
	reg [31:0] done_int;
	
	always @(posedge CLK) begin
		if (done_int == 1) begin
			Divisor_int <= Divisor;
			Divider_int <= Divider;
			remainder_int <= 0;
			result_int <= 0;
			counter_int <= 0;
			done_int <= 0;
		end
		else if (done_int == 0) begin
			if (remainder_int < Divider_int) begin
				remainder_int <= remainder_int;
				result_int <= result_int;
				counter_int <= counter_int;
				done_int <= 1;
			end
			else begin
				remainder_int <= remainder_int - Divider_int;
				result_int <= result_int + 1;
				counter_int <= counter_int + 1;
			end
		end
	end
	assign result = result_int;
	assign remainder = remainder_int;
	assign done = done_int;
endmodule

