   wire            muxSel;

   initial
   begin
      loaded <= 0;
      largest <= 0;
      rand_pat <= 0;
   end

   always @(posedge clk)
   begin
      if (rst)
      begin
         loaded <= 0;
         largest <= 0;
         rand_pat <= 0;
      end
      else
      begin
         if (Wr)
         begin
            mem[Addr] <= DataIn;
            loaded <= 1;
