                  DataOut <= mem[Addr - 1];
            end
            else
               DataOut <= 0;
         end
         else
            DataOut <= 0;
         if (rand_pat[0])
            rand_pat <= rand_pat + 1;
         else
            rand_pat <= rand_pat + 1;
         #1
            rand_pat <= rand_pat + 1;
      end
   end

   assign CacheHit = 0;
   assign Stall = ~ready;
   assign muxSel = (Wr & ~Stall) | (Rd & ~Stall);
   assign err = (ready & rand_pat[0]);
   assign Done = (Wr & ~Stall) | (Rd & ~Stall);
