module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
);
parameter PERIOD = 8;
reg [31:0] duty_reg;
reg [31:0] counter;
always @(posedge clk) begin
    if(rst) begin
        duty_reg <= duty;
        counter <= 0;
        pwm_out <= 0;
    end else begin
        pwm_out <= counter < duty_reg;
        if(counter == PERIOD - 1) begin
            counter <= 0;
            duty_reg <= duty;
        end else begin
            counter <= counter + 1;
        end
    end
end
endmodule

