module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [3*NBITS-1:0] rdata_reg [0 :3*NBITS-1];
  reg [3*NBITS-1:0] rdata_reg2 [0 :3*NBITS-1];
  reg [3*NBITS-1:0] rdata_reg3 [0 :3*NBITS-1];
  reg [3*NBITS-1:0] rdata_reg4 [0 :3*NBITS-1];
  assign hrdata = rdata_reg[3*NBITS-1] | rdata_reg2[3*NBITS-1] | rdata_reg3[3*NBITS-1] | rdata_reg4[3*NBITS-1];
  always @(posedge hclk) begin
    if (hresetn == 1'b0) begin
      rdata_reg[3*NBITS-1] <= 0;
      rdata_reg2[3*NBITS-1] <= 0;
      rdata_reg3[3*NBITS-1] <= 0;
      rdata_reg4[3*NBITS-1] <= 0;
    end else begin
      if (valid_rd == 1'b1) begin
        rdata_reg[3*NBITS-1] <= rdata[3*NBITS-1];
        rdata_reg2[3*NBITS-1] <= rdata[3*NBITS-2];
        rdata_reg3[3*NBITS-1] <= rdata[3*NBITS-3];
        rdata_reg4[3*NBITS-1] <= rdata[3*NBITS-4];
      end
    end
  end
endmodule

