module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [1:0]   state;
reg         load_p1;
reg         load_p2;
reg         s_valid_p1;
reg         s_valid_p2;
reg         s_ready_p1;
reg         s_ready_p2;
reg         m_valid_p1;
reg         m_valid_p2;
reg         m_ready_p1;
reg         m_ready_p2;

assign s_ready = s_ready_p1;
assign m_data  = data_p1;
assign m_valid = m_valid_p1;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state  <= 2'b00;
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        s_valid_p1 <= 1'b0;
        s_valid_p2 <= 1'b0;
        s_ready_p1 <= 1'b0;
        s_ready_p2 <= 1'b0;
        m_valid_p1 <= 1'b0;
        m_valid_p2 <= 1'b0;
        m_ready_p1 <= 1'b0;
        m_ready_p2 <= 1'b0;
    end else begin
        if (load_p1) begin
            data_p1 <= s_data;
            s_valid_p1 <= s_valid;
            s_ready_p1 <= 1'b1;
        end else if (load_p2) begin
            data_p2 <= s_data;
            s_valid_p2 <= s_valid;
            s_ready_p2 <= 1'b1;
        end else begin
            s_ready_p1 <= 1'b0;
            s_ready_p2 <= 1'b0;
        end
        if (m_ready_p1) begin
            m_valid_p1 <= 1'b1;
            m_ready_p1 <= 1'b0;
        end else if (m_ready_p2) begin
            m_valid_p2 <= 1'b1;
            m_ready_p2 <= 1'b0;
        end else begin
            m_valid_p1 <= 1'b0;
            m_valid_p2 <= 1'b0;
        end
        case (state)
            2'b00: begin
                if (s_valid_p1 && s_ready_p2) begin
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    state <= 2'b01;
                end
            end
            2'b01: begin
                if (s_valid_p2 && s_ready_p1) begin
                    load_p1 <= 1'b0;
                    load_p2 <= 1'b1;
                    state <= 2'b10;
                end
            end
            2'b10: begin
                if (s_valid_p1 && s_ready_p2) begin
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    state <= 2'b01;
                end
            end
            default: begin
                load_p1 <= 1'b0;
                load_p2 <= 1'b0;
                state <= 2'b00;
            end
        endcase
    end
end

endmodule

