module uart_send(
  input sys_clk,
  input sys_rst_n,
  input uart_en,
  input [7:0] uart_din,
  output reg uart_txd
);
parameter CLK_FREQ = 100000000;
  parameter UART_BPS = 9600;
  parameter BPS_CNT = CLK_FREQ / UART_BPS;
  reg [31:0] clk_cnt = 0;
  reg [31:0] tx_cnt = 0;
  reg [31:0] tx_data = 0;
  reg tx_flag = 0;
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      tx_flag <= 0;
      tx_cnt <= 0;
      tx_data <= 0;
      clk_cnt <= 0;
    end else begin
      if (tx_flag) begin
        if (tx_cnt == 7) begin
          tx_flag <= 0;
          tx_cnt <= 0;
          tx_data <= 0;
          clk_cnt <= 0;
        end else begin
          tx_cnt <= tx_cnt + 1;
        end
      end else begin
        if (uart_en) begin
          tx_flag <= 1;
          tx_cnt <= 0;
          tx_data <= uart_din;
          clk_cnt <= 0;
        end
      end
    end
  end
  always @(posedge sys_clk or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      uart_txd <= 0;
    end else begin
      if (tx_flag) begin
        if (clk_cnt == BPS_CNT) begin
          uart_txd <= tx_data[7];
          clk_cnt <= 0;
        end else begin
          clk_cnt <= clk_cnt + 1;
        end
      end else begin
        if (clk_cnt == BPS_CNT) begin
          uart_txd <= 1;
          clk_cnt <= 0;
        end else begin
          clk_cnt <= clk_cnt + 1;
        end
      end
    end
  end
endmodule

