module D94_75498(addr, out, clk);
   input clk;
   output [15:0] out;
   input [1:0] addr;
reg [15:0] out, out2, out3;

   always @(posedge clk) begin
      out2 <= out3;
      out <= out2;
      case(addr)
         0: out3 <= 16'h0000;
         1: out3 <= 16'h0001;
         2: out3 <= 16'h0003;
         3: out3 <= 16'h0007;
         default: out3 <= 16'h0000;
      endcase
   end
endmodule

