     input wire clk,
     input wire reset,


     input wire update,
     input wire [WAVE_LEN_WIDTH-1:0] wave_length,
     input wire [WAVE_LEN_WIDTH-1:0] pulse_width,
     input wire active_high,

     output wire [WAVE_LEN_WIDTH-1:0] wave_length_out,
     output wire [WAVE_LEN_WIDTH-1:0] pulse_width_out,
     output wire active_high_out,

     input wire enable,
     output wire pwm_out
     );
reg [WAVE_LEN_WIDTH-1:0] wave_length_reg;
reg [WAVE_LEN_WIDTH-1:0] pulse_width_reg;
reg active_high_reg;
reg [WAVE_LEN_WIDTH-1:0] wave_weight_reg;
reg [WAVE_LEN_WIDTH-1:0] wave_weight_counter;
reg [WAVE_LEN_WIDTH-1:0] wave_length_counter;

assign wave_length_out = wave_length_reg;
assign pulse_width_out = pulse_width_reg;
assign active_high_out = active_high_reg;
assign pwm_out = wave_weight_counter > wave_length_counter ? 1'b0 : active_high_reg ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (reset) begin
        wave_length_reg <= 0;
        pulse_width_reg <= 0;
        active_high_reg <= 0;
        wave_weight_reg <= 0;
        wave_weight_counter <= 0;
        wave_length_counter <= 0;
    end else begin
        if (update) begin
            wave_length_reg <= wave_length;
            pulse_width_reg <= pulse_width;
            active_high_reg <= active_high;
            wave_weight_reg <= wave_weight;
            wave_weight_counter <= 0;
            wave_length_counter <= 0;
        end else begin
            if (wave_weight_counter < wave_weight_reg) begin
                wave_weight_counter <= wave_weight_counter + 1;
            end else begin
                wave_weight_counter <= 0;
                if (wave_length_counter < wave_length_reg) begin
                    wave_length_counter <= wave_length_counter + 1;
                end else begin
                    wave_length_counter <= 0;
                end
            end
        end
    end
end

endmodule

