module peridot_ethio_cdb_signal (
	input wire			reset,
	input wire			clk,
	input wire			in_sig,
	output wire			out_sig,
	output wire			riseedge,
	output wire			falledge
);
reg [2:0]			shift_reg;
	assign out_sig = in_sig;
	assign riseedge = shift_reg[2] & ~shift_reg[1];
	assign falledge = ~shift_reg[2] & shift_reg[1];
	always @(posedge clk) begin
		if (reset) begin
			shift_reg <= 3'b0;
		end else begin
			shift_reg <= {shift_reg[1], in_sig};
		end
	end
endmodule

module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
);
reg [15:0] rd_compl_tag;
reg rd_compl_start;
reg rd_compl_done;
reg bm_tag;
reg bm_done;
reg [15:0] op_tag;
reg op_done;
assign OP_TAG = rd_compl_start ? rd_compl_tag : bm_tag;
assign OP_DONE = rd_compl_start ? rd_compl_done : bm_done;
always @(posedge CLK) begin
    if(RESET) begin
        rd_compl_tag <= 0;
        rd_compl_start <= 0;
        rd_compl_done <= 0;
        bm_tag <= 0;
        bm_done <= 0;
        op_tag <= 0;
        op_done <= 0;
    end else begin
        if(RD_COMPL_START) begin
            rd_compl_tag <= RD_COMPL_TAG;
            rd_compl_start <= 1;
            rd_compl_done <= 0;
        end else if(RD_COMPL_DONE) begin
            rd_compl_start <= 0;
            rd_compl_done <= 1;
        end
        if(BM_DONE) begin
            bm_tag <= BM_TAG;
            bm_done <= 1;
        end
    end
end
endmodule

