module mips_alu(zero, result, alu_op, first_data, second_data, shamt);
output reg zero;					
	output reg [31:0] result;
	input [31:0] first_data;		
	input [31:0] second_data;		
	input [3:0] alu_op;				
	input [4:0] shamt;
reg [31:0] add_result, sub_result, and_result, or_result, nor_result, shift_result;
	reg [31:0] shift_amount;

	always @* begin
		zero = 0;
		result = 0;
		shift_amount = 0;
		case (alu_op)
			0: begin
				add_result = first_data + second_data;
				if (add_result == 0) begin
					zero = 1;
				end
			end
			1: begin
				sub_result = first_data - second_data;
				if (sub_result == 0) begin
					zero = 1;
				end
			end
			2: begin
				and_result = first_data & second_data;
				if (and_result == 0) begin
					zero = 1;
				end
			end
			3: begin
				or_result = first_data | second_data;
				if (or_result == 0) begin
					zero = 1;
				end
			end
			4: begin
				nor_result = ~(first_data | second_data);
				if (nor_result == 0) begin
					zero = 1;
				end
			end
			5: begin
				shift_result = first_data << shamt;
				if (shift_result == 0) begin
					zero = 1;
				end
			end
			6: begin
				shift_result = first_data >> shamt;
				if (shift_result == 0) begin
					zero = 1;
				end
			end
			7: begin
				shift_result = first_data >>> shamt;
				if (shift_result == 0) begin
					zero = 1;
				end
			end
			8: begin
				shift_result = second_data << shamt;
				if (shift_result == 0) begin
					zero = 1;
				end
			end
			9: begin
				shift_result = second_data >> shamt;
				if (shift_result == 0) begin
					zero = 1;
				end
			end
			10: begin
				shift_result = second_data >>> shamt;
				if (shift_result == 0) begin
					zero = 1;
				end
			end
			default: begin
				zero = 0;
			end
		endcase
	end
endmodule

module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg  mainclk;
reg  updateclk;
reg  capture;
reg  update;


always @ (captnupdt or shiftnld or clk) begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11: begin
            updateclk = clk;
            capture = 1'b1;
        end
        2'b01: begin
            updateclk = clk;
            capture = 1'b0;
        end
        default: begin
            mainclk = clk;
            update = 1'b1;
        end
    endcase
end

initial begin
    mainclk = 1'b0;
    updateclk = 1'b0;
    capture = 1'b0;
    update = 1'b0;
end

endmodule

