module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma, undersampled_sigma;
	reg [31:0] delta;
	wire [31:0] deriv;

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
		end else begin
			if (ock) begin
				if (sdi) begin
					sigma <= sigma + 1;
				end else begin
					sigma <= sigma - 1;
				end
			end
			if (uck) begin
				if (sdi) begin
					undersampled_sigma <= undersampled_sigma + 1;
				end else begin
					undersampled_sigma <= undersampled_sigma - 1;
				end
			end
		end
	end

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			delta <= 0;
		end else begin
			if (sdi) begin
				delta <= undersampled_sigma - sigma;
			end else begin
				delta <= sigma - undersampled_sigma;
			end
		end
	end

	assign deriv = signed_data ? delta : -delta;
	assign dout = signed_data ? {31{delta[31]} + delta} : {31{delta[31]} - delta};
endmodule

module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] RegFile [31:0];
    always @(negedge Clk)
    begin
        if(ReadReg1 != 0)
            ReadData1 <= RegFile[ReadReg1];
        else
            ReadData1 <= 0;
        if(ReadReg2 != 0)
            ReadData2 <= RegFile[ReadReg2];
        else
            ReadData2 <= 0;
    end
    always @(posedge Clk)
    begin
        if(RegWrite)
            RegFile[WriteReg] <= WriteData;
    end
endmodule

module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);
parameter Vcc = 1.2;
    parameter C_L = 1.0;
    parameter t_hmin = 0.0;
    parameter t_hmax = 0.0;
    integer counter = 0;
    always @(posedge CLK) begin
        if (CLR_BAR) begin
            Q <= 0;
        end else begin
            Q <= D;
        end
    end
    always @(posedge CLK) begin
        if (CLR_BAR) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end
    always @(posedge CLK) begin
        if (CLR_BAR) begin
            $display("Power dissipation: %d", counter * C_L * Vcc^2);
        end
    end
endmodule

