module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
reg [SIZE-1:0]state, toggle, Zeros = 0;
always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= Zeros;
	else
		if (enable)
			state <= {toggle[0], state[SIZE-2:1] ^ state[SIZE-3:0]};
end
always @(state)
begin
	toggle[0] = 1;
	toggle[1] = state[SIZE-2] ^ state[SIZE-3];
	toggle[2] = state[SIZE-3] ^ state[SIZE-4];
	toggle[3] = state[SIZE-4] ^ state[SIZE-5];
end
assign gray_out = state[SIZE-1:0];
endmodule

