module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
reg [31:0] r_count;
  reg [1:0] state;
  reg [1:0] state_next;

  always @(posedge clk) begin
    if (rst) begin
      r_count <= 0;
      state <= IDLE;
    end else begin
      case (state)
      IDLE: begin
        if (i_ppfifo_rdy[0]) begin
          state <= READY;
        end
      end
      READY: begin
        if (i_h_blank) begin
          if (i_v_sync) begin
            if (r_count < i_ppfifo_size) begin
              o_ppfifo_stb <= 1;
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end else begin
              o_ppfifo_stb <= 0;
            end
          end else begin
            o_ppfifo_stb <= 0;
          end
        end else begin
          if (i_v_sync) begin
            if (r_count < i_ppfifo_size) begin
              o_ppfifo_stb <= 1;
              o_ppfifo_data <= i_rgb;
              r_count <= r_count + 1;
            end else begin
              o_ppfifo_stb <= 0;
            end
          end else begin
            o_ppfifo_stb <= 0;
          end
        end
      end
      RELEASE: begin
        o_ppfifo_stb <= 0;
        o_ppfifo_act <= 0;
        r_count <= 0;
        state <= IDLE;
      end
      default: begin
        o_ppfifo_stb <= 0;
        o_ppfifo_act <= 0;
        r_count <= 0;
        state <= IDLE;
      end
      endcase
    end
  end

  always @(*) begin
    case (state)
    IDLE: state_next = IDLE;
    READY: state_next = IDLE;
    RELEASE: state_next = IDLE;
    default: state_next = IDLE;
    endcase
  end

endmodule

