module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	data_regnum;
	reg 	data_out_sign;
	reg 	data_ok;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			data_reg <= 0;
			data_regnum <= 0;
			data_out_sign <= 0;
			data_ok <= 0;
		end else begin
			if (data_in_sign) begin
				data_reg <= data_reg + data_in;
				data_regnum <= data_regnum + 1;
			end
			if (data_regnum == 8) begin
				if (data_reg == 28 || data_reg == 36) begin
					data_ok <= 1;
				end
			end
			if (data_valid) begin
				data_out_sign <= 1;
				data_out <= data_out + 1;
			end
		end
	end
endmodule

module counter (rstn, clk, up, down, count); input rstn; input clk; input up; input down; output [WIDTH-1:0] count;
parameter WIDTH = 8;
reg [WIDTH-1:0] count_int;
always @(posedge clk) begin if (rstn == 0) count_int <= 0; else if (up == 1) count_int <= count_int + 1; else if (down == 1) count_int <= count_int - 1; end assign count = count_int; endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
);
reg clk_out = 0;
reg [31:0] ticks = 499999;
assign clk_100Hz = clk_out;
always @(posedge clk_100MHz) begin
    if(reset) begin
        ticks <= 499999;
        clk_out <= 0;
    end else begin
        ticks <= ticks + 1;
        if(ticks == 0) begin
            clk_out <= ~clk_out;
        end
    end
end
endmodule

