begin
if(en)
begin
pc<=pc+1;
end
else
begin
pc<=0;
end
end
always @(negedge clkin)
begin
if(en)
begin
nc<=nc+1;
end
else
begin
nc<=0;
end
end
always @(posedge clkout)
begin
if(n%2==0)
begin
if(pc==n/2)
begin
clkout<=1;
end
else
begin
clkout<=0;
end
end
else
begin
if(pc==(n/2)+1)
begin
clkout<=1;
end
else
begin
clkout<=0;
end
end
end
endmodule

