module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter Divider = 100000;
reg [26:0] Counter;
always @(posedge Clock) begin
	if(MR) begin
		Counter <= 0;
		Timeout <= 0;
	end else if(Counter == Divider) begin
		Counter <= 0;
		Timeout <= 1;
	end else begin
		Counter <= Counter + 1;
		Timeout <= 0;
	end
end
endmodule

module counter_ex3(
input wire clk,
input wire clr,
input wire cnten,
output wire [15:0] q
);
reg [15:0] cnt;
  always @(posedge clk, posedge clr, posedge cnten) begin
    if(clr == 1'b1) begin
      cnt <= {16{1'b0}};
    end else if(cnten == 1'b1) begin
      if(cnt == 15'd999) begin
        cnt <= {16{1'b0}};
      end else begin
        cnt <= cnt + 1;
      end
    end
  end
  assign q = cnt;
endmodule

