module TopModule(
    clk,
    resetn,
    x,
    y,
    f,
    g
);

reg [1:0] state;
    reg f, g;

    always @(posedge clk) begin
        if (resetn == 0) begin
            state <= 0;
            f <= 0;
            g <= 0;
        end else begin
            case (state)
                0: begin
                    if (x == 1) begin
                        state <= 1;
                    end
                end
                1: begin
                    if (x == 1) begin
                        state <= 2;
                    end else if (x == 0) begin
                        state <= 1;
                    end
                end
                2: begin
                    if (x == 1) begin
                        state <= 3;
                    end else if (x == 0) begin
                        state <= 2;
                    end
                end
                3: begin
                    if (y == 1) begin
                        state <= 4;
                    end
                end
                4: begin
                    if (y == 1) begin
                        g <= 1;
                    end else begin
                        g <= 0;
                    end
                end
                default: begin
                    state <= 0;
                end
            endcase
            if (state == 0) begin
                f <= 0;
            end else if (state == 1) begin
                f <= 1;
            end else if (state == 2) begin
                f <= 0;
            end else if (state == 3) begin
                f <= 0;
            end else if (state == 4) begin
                f <= 0;
            end
        end
    end

endmodule

