    if (arst) begin
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        aaah <= 1'b0;
    end else begin
        if (ground == 1'b0) begin
            aaah <= 1'b1;
            if (bump_left == 1'b1) begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
