            aaah <= 1'b0;
            if (bump_left == 1'b1) begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else if (bump_right == 1'b1) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
