module TopModule(
    clk,
    load,
    data,
    q
);

reg [15:0] q;
    reg [15:0] q_next;

    always @(posedge clk) begin
        q_next <= q;
        if (load) begin
            q_next <= data;
        end else begin
            for (int i = 0; i < 16; i++) begin
                for (int j = 0; j < 16; j++) begin
                    int n = 0;
                    if (i > 0) n += q[i-1][j];
                    if (i < 15) n += q[i+1][j];
                    if (j > 0) n += q[i][j-1];
                    if (j < 15) n += q[i][j+1];
                    if (n == 0) q_next[i][j] = 0;
                    else if (n == 1) q_next[i][j] = 0;
                    else if (n == 2) q_next[i][j] = q[i][j];
                    else if (n == 3) q_next[i][j] = 1;
                    else q_next[i][j] = 0;
                end
            end
        end
    end

endmodule

module TopModule(
    clk,
    in,
