    done
);

reg [7:0] out_byte;
reg done;

always @(posedge clk) begin
    if (reset) begin
        out_byte <= 8'b0;
        done <= 0;
    end else begin
        if (in == 0) begin
            out_byte <= 8'b0;
            done <= 0;
        end else if (in == 1) begin
            out_byte <= out_byte << 1;
            done <= 0;
        end else begin
            out_byte <= out_byte << 1;
            out_byte[0] <= in;
            if (in == 1) begin
                done <= 1;
            end
        end
    end
end

endmodule

