    dig,
    walk_left,
    walk_right,
    aaah,
    digging
);

reg [1:0] state;
reg [1:0] next_state;

assign walk_left = state[0];
assign walk_right = state[1];
assign aaah = (state[0] == 1 && state[1] == 0) ? 1 : 0;
assign digging = (state[0] == 1 && state[1] == 0 && ground == 1) ? 1 : 0;

always @(posedge clk) begin
    if (arst) begin
        state <= 2'b00;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        2'b00: begin
            if (bump_left) begin
                next_state = 2'b01;
            end else if (bump_right) begin
                next_state = 2'b10;
            end else if (ground == 0) begin
                next_state = 2'b01;
            end else begin
                next_state = 2'b00;
            end
        end
        2'b01: begin
            if (bump_left) begin
                next_state = 2'b10;
            end else if (bump_right) begin
                next_state = 2'b00;
            end else if (ground == 0) begin
                next_state = 2'b01;
            end else begin
                next_state = 2'b01;
            end
        end
        2'b10: begin
            if (bump_left) begin
                next_state = 2'b00;
            end else if (bump_right) begin
                next_state = 2'b10;
            end else if (ground == 0) begin
                next_state = 2'b01;
            end else begin
                next_state = 2'b10;
            end
        end
        default: begin
            next_state = 2'b00;
        end
    endcase
end

