module TopModule(
    clk,
    reset,
    data,
    count,
    counting,
    done,
    ack
);

reg [3:0] count;
reg counting;
reg done;
reg [3:0] delay;

always @(posedge clk) begin
    if (reset) begin
        count <= 4'b0000;
        counting <= 0;
        done <= 0;
        delay <= 4'b0000;
    end else begin
        if (counting) begin
            count <= count - 1;
            if (count == 0) begin
                counting <= 0;
                done <= 1;
            end
        end else if (data == 4'b1101) begin
            count <= 4'b0000;
            counting <= 1;
            delay <= data;
        end
    end
end

endmodule
